const body = $input.first().json.body || $input.first().json;
const prop = body.property || body;

if (!prop.project_name && !prop.caption && !prop.title) {
  throw new Error('Validation Failed: Missing project name or caption');
}

return {
  json: {
    execution_id: body.execution_id || 'exec-' + Date.now(),
    source: body.source || 'BoltHavenProperty',
    event: body.event || 'property.process',
    valid: true,
    validated_at: new Date().toISOString(),
    property: prop
  }
};

const item = $input.first().json;
const p = item.property || {};

const normalizedPrice = Number(p.monthly_rent_thb || p.rentPrice || 0);
const normalizedBeds = Number(p.bedrooms || 1);
const normalizedArea = Number(p.area_sqm || p.sizeSqm || 0);
const name = p.project_name || p.title || 'Featured Property';

const formattedSummary = `🏢 ${name}\n💰 Rent: ฿${normalizedPrice.toLocaleString()}/mo\n🛏️ ${normalizedBeds} Bed | 📐 ${normalizedArea} sqm\n✨ Automated via BoltHaven n8n Engine`;

return {
  json: {
    execution_id: item.execution_id,
    status: 'success',
    workflow_name: 'Property Content Processing',
    normalized_property: {
      name: name,
      monthly_rent: normalizedPrice,
      bedrooms: normalizedBeds,
      area_sqm: normalizedArea,
      images_count: (p.images || []).length,
      summary: formattedSummary
    },
    formatted_summary: formattedSummary,
    processed_at: new Date().toISOString()
  }
};
